import { describe, expect, it } from "vitest";
import { screen } from "@testing-library/react";
import { RasaCodeBlock } from "./RasaCodeBlock";
import { renderWithProviders } from "./tests/utils";

const readMaxCodeHeight = (testId: string) =>
  getComputedStyle(screen.getByTestId(testId)).getPropertyValue("--code-block-max-height");

describe("RasaCodeBlock", () => {
  it("caps the scrollable code area at the given sizes token", () => {
    renderWithProviders(<RasaCodeBlock code="const a = 1;" maxCodeHeight="96" data-testid="cb" />);

    expect(readMaxCodeHeight("cb")).toContain("sizes-96");
  });

  it("leaves the code area uncapped when no height is given", () => {
    renderWithProviders(<RasaCodeBlock code="const a = 1;" data-testid="cb" />);

    expect(readMaxCodeHeight("cb")).not.toContain("sizes");
  });
});
